# pip install flask 后运行本文件,浏览器访问 /
from flask import Flask

app = Flask(__name__)

@app.route('/', methods=['GET'])
def index():
    return 'Hello, Flask'

@app.route('/user/<name>')
def user(name):
    return f'用户: {name}'

if __name__ == '__main__':
    # app.run(debug=True)  ← 本地演示用
    with app.test_client() as c:
        print(c.get('/').data.decode())
        print(c.get('/user/Alice').data.decode())

from flask import Flask, jsonify, request

app = Flask(__name__)
todos = []

@app.post('/todos')
def create():
    data = request.get_json()
    todos.append(data['title'])
    return jsonify({'title': data['title']}), 201

@app.get('/todos')
def listing():
    return jsonify(todos)

with app.test_client() as c:
    print(c.post('/todos', json={'title': '学Flask'}).status_code)
    print(c.get('/todos').data.decode())
